export type ParsedDepositTokenInstruction<
  TProgram extends string = typeof NEST_VAULT_PROGRAM_ADDRESS,
  TAccountMetas extends readonly AccountMeta[] = readonly AccountMeta[],
> = {
  programAddress: Address<TProgram>
  accounts: {
    depositor: TAccountMetas[0]
    vault: TAccountMetas[1]
    mint: TAccountMetas[2]
    depositorToken: TAccountMetas[3]
    vaultToken: TAccountMetas[4]
    tokenProgram: TAccountMetas[5]
    associatedTokenProgram: TAccountMetas[6]
    systemProgram: TAccountMetas[7]
  }
  data: DepositTokenInstructionData
}

export function parseDepositTokenInstruction<TProgram extends string, TAccountMetas extends readonly AccountMeta[]>(
  instruction: Instruction<TProgram> & InstructionWithAccounts<TAccountMetas> & InstructionWithData<ReadonlyUint8Array>,
): ParsedDepositTokenInstruction<TProgram, TAccountMetas> {
  if (instruction.accounts.length < 8) {
    throw new SolanaError(SOLANA_ERROR__PROGRAM_CLIENTS__INSUFFICIENT_ACCOUNT_METAS, {
      actualAccountMetas: instruction.accounts.length,
      expectedAccountMetas: 8,
    })
  }
  let accountIndex = 0
  const getNextAccount = () => {
    const accountMeta = (instruction.accounts as TAccountMetas)[accountIndex]!
    accountIndex += 1
    return accountMeta
  }
  return {
    programAddress: instruction.programAddress,
    accounts: {
      depositor: getNextAccount(),
      vault: getNextAccount(),
      mint: getNextAccount(),
      depositorToken: getNextAccount(),
      vaultToken: getNextAccount(),
      tokenProgram: getNextAccount(),
      associatedTokenProgram: getNextAccount(),
      systemProgram: getNextAccount(),
    },
    data: getDepositTokenInstructionDataDecoder().decode(instruction.data),
  }
}
